// The intro's six stills: the owner's pictures, shrunk to the game's picture and its 64 colours by
// tools/unruggabull-ii/intro/stills.py. The source pictures aren't kept in the repo; this data is the art.
// Classic script: UnrugIntroStills.stills[i] is { w, h, img } for still i + 1, in picture pixels (480 x 270; still 5
// is 480 x 540); UnrugIntroStills.sprites holds the Rugfather's frames the intro needs besides portrait.js.
var UnrugIntroStills = (function () {
  'use strict';
  const load = s => { const img = new Image(); img.src = s.src; return { w: s.w, h: s.h, img }; };
  const stills = [
    { w: 480, h: 270, src: 'data:image/webp;base64,' },
    { w: 480, h: 270, src: 'data:image/webp;base64,' },
    { w: 480, h: 270, src: 'data:image/webp;base64,' },
    { w: 480, h: 270, src: 'data:image/webp;base64,' },
    { w: 480, h: 540, src: 'data:image/webp;base64,' },
    { w: 480, h: 270, src: 'data:image/webp;base64,' }
  ].map(load);
  const sprites = {
    reach: { w: 95, h: 126, src: 'data:image/webp;base64,' },
    heap: { w: 116, h: 90, src: 'data:image/webp;base64,' }
  };
  for (const k in sprites) sprites[k] = load(sprites[k]);
  return { stills, sprites };
})();
